@extends('layouts.app') @section('title','Pergerakan Stok') @section('heading','Pergerakan Stok') @section('content')<p class="muted page-intro">Setiap transaksi masuk/keluar memperbarui stok dan disimpan sebagai riwayat.</p><div class="panel form-panel"><div class="panel-heading"><div><h3>Catat Transaksi</h3><p>Stok keluar tidak dapat melebihi stok tersedia.</p></div></div><form method="post" action="{{ route('stock.store') }}">@csrf<div class="form-grid"><div><label>Produk <span>*</span></label><select name="product_id" required><option value="">Pilih produk</option>@foreach($products as $p)<option value="{{ $p->id }}" @selected(old('product_id')==$p->id)>{{ $p->sku }} — {{ $p->name }} (stok: {{ $p->stock }})</option>@endforeach</select></div><div><label>Jenis Transaksi <span>*</span></label><select name="type" required><option value="IN" @selected(old('type')==='IN')>Stok Masuk</option><option value="OUT" @selected(old('type')==='OUT')>Stok Keluar</option></select></div><div><label>Jumlah <span>*</span></label><input type="number" name="quantity" min="1" required value="{{ old('quantity',1) }}"></div><div><label>Catatan</label><input name="note" maxlength="255" value="{{ old('note') }}" placeholder="Catatan opsional"></div></div><div class="form-actions"><button class="btn primary">Simpan Transaksi</button></div></form></div><div class="panel"><div class="panel-heading"><div><h3>Riwayat Transaksi</h3><p>20 transaksi terbaru per halaman.</p></div></div><div class="table-wrap"><table><thead><tr><th>Tanggal</th><th>Produk</th><th>Jenis</th><th>Jumlah</th><th>Petugas</th><th>Catatan</th></tr></thead><tbody>@forelse($movements as $m)<tr><td>{{ $m->created_at?->format('d/m/Y H:i') }}</td><td>{{ $m->product->name }}</td><td><span class="pill {{ $m->type==='IN'?'success':'warning' }}">{{ $m->type==='IN'?'Masuk':'Keluar' }}</span></td><td>{{ $m->quantity }}</td><td>{{ $m->user->name ?? '—' }}</td><td>{{ $m->note ?: '—' }}</td></tr>@empty<tr><td colspan="6" class="empty">Belum ada transaksi stok.</td></tr>@endforelse</tbody></table></div><div class="pagination">{{ $movements->links() }}</div></div>@endsection